package com.oms.web.servlet;import com.oms.model.Module;import com.oms.service.*;import com.oms.web.Json;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;import java.math.BigDecimal;import java.sql.SQLException;import java.util.*;
@WebServlet({"/inventory/counts","/inventory/counts/create","/inventory/counts/save","/inventory/counts/post"})public class InventoryCountPageServlet extends BaseServlet{private final PermissionService permissions=new PermissionService();private final InventoryCountService service=new InventoryCountService();@Override protected void doGet(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{try{q.setAttribute("canWrite",permissions.policy().canWrite(currentUser(q).getRoles(),Module.INVENTORY));q.setAttribute("countData",Json.encode(service.page()).replace("<","\\u003c"));render(q,p,"inventory/counts");}catch(SQLException e){throw new ServletException(e);}}@Override protected void doPost(HttpServletRequest q,HttpServletResponse p)throws IOException{p.setContentType("application/json;charset=UTF-8");try{switch(q.getServletPath()){case "/inventory/counts/create"->service.create(longParam(q,"warehouseId"),param(q,"note"),currentUser(q));case "/inventory/counts/save"->service.count(longParam(q,"id"),values(q),currentUser(q));case "/inventory/counts/post"->service.post(longParam(q,"id"),currentUser(q));default->{error(p,405,"Thao tác không hợp lệ.");return;}}p.getWriter().write("{\"ok\":true}");}catch(ServiceException|IllegalArgumentException e){error(p,400,e.getMessage());}catch(SQLException e){log("Không xử lý được kiểm kê",e);error(p,500,"Không thể xử lý phiếu kiểm kê.");}}private static List<BigDecimal> values(HttpServletRequest q){List<BigDecimal>x=new ArrayList<>();String[]v=q.getParameterValues("actual");if(v==null)return x;for(String s:v)try{x.add(new BigDecimal(s));}catch(NumberFormatException e){throw new ServiceException("Tồn thực tế không hợp lệ.");}return x;}private static void error(HttpServletResponse p,int s,String m)throws IOException{p.setStatus(s);p.getWriter().write(Json.encode(Map.of("error",m)));}}
